export type ThemeMode = "dark" | "light" | "system";

/**
 * Theme palettes in the omarchy `colors.toml` format.
 *
 * Ported from the tasks app (products/tasks/src/backend/themePalette.ts) with the same slot
 * names and the same derivation rules, so a palette file from there is a valid theme here.
 * Pure module: no DOM, so the server can build CSS from it.
 *
 * Two names collide with shadcn and are mapped deliberately in theme.css: omarchy `accent`
 * is the brand color (our `--primary` and focus ring), while shadcn `--accent` is a quiet
 * hover surface and takes omarchy `selection`.
 */

/** Canonical omarchy slot name to hex color, for example `dark_background`. */
export type ThemePalette = Record<string, string>;

/** What the client needs to list a theme and draw its swatch. Colors are any CSS color. */
export type ThemeOption = {
  name: string;
  label: string;
  mode: ThemeMode;
  accent: string;
  canvas: string;
  /** Left out of the picker unless it is the active theme; something else on the site unlocks it. */
  hidden?: boolean;
};

const HEX_COLOR = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i;
const ASSIGNMENT = /^([A-Za-z0-9_.-]+)[ \t]*=[ \t]*(.*)$/;
const MODES: readonly string[] = ["dark", "light", "system"];

type Rgb = { r: number; g: number; b: number };

function parseHexColor(value: string): Rgb {
  const digits = value.slice(1);
  const expanded = digits.length === 3 ? [...digits].map((digit) => digit + digit).join("") : digits;
  return {
    r: Number.parseInt(expanded.slice(0, 2), 16),
    g: Number.parseInt(expanded.slice(2, 4), 16),
    b: Number.parseInt(expanded.slice(4, 6), 16),
  };
}

function toHex({ r, g, b }: Rgb): string {
  const channel = (value: number): string =>
    Math.round(Math.min(255, Math.max(0, value))).toString(16).padStart(2, "0");
  return `#${channel(r)}${channel(g)}${channel(b)}`;
}

/** Expands three-digit hex so palettes reach the page in one shape. */
function normalizeHex(value: string): string {
  const digits = value.slice(1);
  if (digits.length !== 3) return value.toLowerCase();
  return `#${[...digits].map((digit) => digit + digit).join("")}`.toLowerCase();
}

function toLinear(value: number): number {
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
}

function fromLinear(value: number): number {
  return value <= 0.0031308 ? value * 12.92 : 1.055 * value ** (1 / 2.4) - 0.055;
}

function relativeLuminance(value: string): number {
  const { r, g, b } = parseHexColor(value);
  return 0.2126 * toLinear(r / 255) + 0.7152 * toLinear(g / 255) + 0.0722 * toLinear(b / 255);
}

function contrastRatio(first: string, second: string): number {
  const a = relativeLuminance(first);
  const b = relativeLuminance(second);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

/** Mixes in linear light: fraction 0 returns `first`, 1 returns `second`. */
function mixHex(first: string, second: string, fraction: number): string {
  const left = parseHexColor(first);
  const right = parseHexColor(second);
  const weight = Math.min(1, Math.max(0, fraction));
  const channel = (a: number, b: number): number =>
    fromLinear(toLinear(a / 255) + (toLinear(b / 255) - toLinear(a / 255)) * weight) * 255;
  return toHex({
    r: channel(left.r, right.r),
    g: channel(left.g, right.g),
    b: channel(left.b, right.b),
  });
}

/**
 * Mixes `from` toward `toward` in tenths until the result reads against every surface at
 * `target` contrast. Roles that carry text are corrected here rather than trusted.
 */
function readableMix(from: string, toward: string, surfaces: string[], target: number): string {
  for (let step = 0; step <= 10; step += 1) {
    const candidate = mixHex(from, toward, step / 10);
    if (surfaces.every((surface) => contrastRatio(candidate, surface) >= target)) return candidate;
  }
  return toward;
}

function paletteValue(rawValue: string): string | undefined {
  const value = rawValue.trim();
  const quote = value[0];
  if (quote === '"' || quote === "'") {
    const end = value.indexOf(quote, 1);
    return end > 0 ? value.slice(1, end) : undefined;
  }
  const comment = value.indexOf("#");
  const bare = (comment === -1 ? value : value.slice(0, comment)).trim();
  return bare === "" ? undefined : bare;
}

/** Reads the flat `key = "value"` subset of TOML that omarchy palettes use. */
function parseColorsToml(text: string): { palette: ThemePalette; mode?: ThemeMode } {
  const palette: ThemePalette = {};
  let mode: ThemeMode | undefined;

  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#") || line.startsWith("[")) continue;
    const assignment = ASSIGNMENT.exec(line);
    const value = assignment ? paletteValue(assignment[2]) : undefined;
    if (!assignment || value === undefined) continue;

    if (assignment[1] === "mode") {
      if (MODES.includes(value)) mode = value as ThemeMode;
    } else {
      palette[assignment[1]] = value;
    }
  }

  return { palette, mode };
}

/**
 * Parses a palette file and fills the slots the page needs from the ones it declares:
 * `on_accent` and `on_red` (ink on a fill) and `muted_foreground` (secondary text) are
 * derived to stay readable, and a file may set any of them directly.
 */
export function parseThemeFile(text: string): { mode: ThemeMode; palette: ThemePalette } {
  const parsed = parseColorsToml(text);
  const colors: ThemePalette = {};
  for (const [key, value] of Object.entries(parsed.palette)) {
    if (HEX_COLOR.test(value)) colors[key] = normalizeHex(value);
  }

  const { background, foreground } = colors;
  if (!background || !foreground) throw new Error("a theme needs at least a background and a foreground");

  const mode = parsed.mode ?? (relativeLuminance(background) < 0.4 ? "dark" : "light");
  const dark = mode === "dark";
  const accent = colors.accent ?? colors.blue ?? foreground;
  const darkBackground = colors.dark_background
    ?? (dark ? mixHex(background, "#000000", 0.25) : mixHex(background, foreground, 0.05));
  const darkerBackground = colors.darker_background
    ?? (dark ? mixHex(background, "#000000", 0.45) : mixHex(background, foreground, 0.1));
  const lighterBackground = colors.lighter_background ?? mixHex(background, foreground, dark ? 0.12 : 0.06);
  const brightForeground = colors.bright_foreground ?? foreground;
  const darkForeground = colors.dark_foreground ?? mixHex(foreground, background, 0.45);

  // Ink on a fill is the theme's own darkest or lightest stop, whichever reads better. A fixed
  // lightness threshold misfires on mid-tone accents, where it picks light ink under 3:1 while
  // the dark stop clears 4.5:1.
  function inkOn(fill: string, darkStop: string, lightStop: string): string {
    return contrastRatio(fill, darkStop) >= contrastRatio(fill, lightStop) ? darkStop : lightStop;
  }
  const red = colors.red ?? (dark ? "#f87171" : "#b91c1c");

  return {
    mode,
    palette: {
      ...colors,
      accent,
      on_accent: colors.on_accent
        ?? inkOn(accent, dark ? darkerBackground : foreground, dark ? brightForeground : background),
      on_red: colors.on_red
        ?? inkOn(red, dark ? darkerBackground : foreground, dark ? brightForeground : background),
      selection: colors.selection ?? mixHex(background, foreground, dark ? 0.18 : 0.12),
      muted: colors.muted ?? mixHex(background, foreground, dark ? 0.3 : 0.22),
      dark_background: darkBackground,
      darker_background: darkerBackground,
      lighter_background: lighterBackground,
      dark_foreground: darkForeground,
      light_foreground: colors.light_foreground ?? mixHex(foreground, background, 0.15),
      bright_foreground: brightForeground,
      // Secondary text lands on the card, the canvas, and raised chips, and omarchy's
      // `dark_foreground` is usually too dim for all three.
      muted_foreground: colors.muted_foreground
        ?? readableMix(darkForeground, foreground, [background, darkBackground, lighterBackground], 4.5),
      red,
    },
  };
}

import { parseThemeFile, type ThemeOption, type ThemePalette } from "./palette";

/**
 * Builds what the root layout inlines for the themes: one CSS block per theme (so switching never
 * waits on the network) and a tiny script that restores the stored choice before first paint.
 * Call it from server code; the client gets plain `ThemeOption`s as props, so the TOML never ships
 * to the browser.
 */

/** A theme written as an omarchy `colors.toml` body. */
export type PaletteTheme = { name: string; label: string; toml: string; hidden?: boolean };

/** A theme with no palette, whose tokens are hand-written CSS on `[data-theme="<name>"]`. */
export type CssTheme = ThemeOption & { palette: ThemePalette };

export type ThemeHeadConfig = {
  themes: (PaletteTheme | CssTheme)[];
  /** The theme a first visit gets, and the one the server renders. */
  defaultTheme: string;
  /** Where the visitor's choice is remembered in localStorage. */
  storageKey: string;
};

/** Palette slots exposed to CSS as `--om-*`, the ones theme.css maps onto shadcn tokens. */
const PALETTE_SLOTS = [
  "accent",
  "on_accent",
  "on_red",
  "background",
  "dark_background",
  "darker_background",
  "lighter_background",
  "selection",
  "muted",
  "foreground",
  "dark_foreground",
  "light_foreground",
  "bright_foreground",
  "muted_foreground",
  "red",
  "orange",
  "yellow",
  "green",
  "cyan",
  "blue",
  "magenta",
  "brown",
];

const declarations = (palette: ThemePalette): string =>
  PALETTE_SLOTS.filter((slot) => palette[slot] !== undefined)
    .map((slot) => `--om-${slot.replaceAll("_", "-")}:${palette[slot]}`)
    .join(";");

const resolve = (theme: PaletteTheme | CssTheme): CssTheme => {
  if (!("toml" in theme)) return theme;
  const { name, label, toml, hidden } = theme;
  const { mode, palette } = parseThemeFile(toml);
  return { name, label, mode, palette, accent: palette.accent, canvas: palette.dark_background, hidden };
};

export function createThemeHead({ themes, defaultTheme, storageKey }: ThemeHeadConfig) {
  // The default leads, the rest follow alphabetically; the picker lists them in this order.
  const records = themes
    .map(resolve)
    .sort((a, b) => Number(b.name === defaultTheme) - Number(a.name === defaultTheme) || a.label.localeCompare(b.label));

  if (!records.some((theme) => theme.name === defaultTheme)) throw new Error(`unknown default theme "${defaultTheme}"`);

  const themeOptions: ThemeOption[] = records.map(({ name, label, mode, accent, canvas, hidden }) => ({
    name,
    label,
    mode,
    accent,
    canvas,
    ...(hidden ? { hidden } : {}),
  }));

  /** A theme with no palette styles itself from hand-written CSS instead. */
  const themeStyles = records
    .filter(({ palette }) => Object.keys(palette).length > 0)
    .map(({ name, palette }) => `[data-theme="${name}"]{${declarations(palette)}}`)
    .join("\n");

  const defaultThemeIsDark = records.find((theme) => theme.name === defaultTheme)?.mode === "dark";

  const modes = Object.fromEntries(records.map(({ name, mode }) => [name, mode]));

  /** Runs in <head> before paint. Mirrors `setTheme` in provider.tsx. */
  const themeScript = `(function(){try{var m=${JSON.stringify(modes)},r=document.documentElement,t=localStorage.getItem(${JSON.stringify(storageKey)});if(!Object.hasOwn(m,t))t=${JSON.stringify(defaultTheme)};r.dataset.theme=t;r.classList.toggle("dark",m[t]==="dark"||(m[t]==="system"&&matchMedia("(prefers-color-scheme: dark)").matches))}catch(e){}})()`;

  return { themeOptions, themeStyles, themeScript, defaultThemeIsDark };
}

"use client"

import * as React from "react"
import type { ThemeMode, ThemeOption } from "./palette"

type ThemeContextValue = {
  /** Active theme name; undefined until the client has read the page, so the server renders no guess. */
  theme: string | undefined
  /** Whether the active theme is currently drawn dark; undefined until read. */
  resolvedMode: "dark" | "light" | undefined
  themes: ThemeOption[]
  setTheme: (name: string) => void
}

const ThemeContext = React.createContext<ThemeContextValue | null>(null)

// The page state lives on <html> (data-theme and .dark), where the blocking script in the root
// layout puts it before first paint. React subscribes to it instead of keeping a copy.
const listeners = new Set<() => void>()
const subscribe = (listener: () => void) => {
  listeners.add(listener)
  return () => listeners.delete(listener)
}
const notify = () => listeners.forEach((listener) => listener())

const readTheme = () => document.documentElement.dataset.theme
const readMode = () => (document.documentElement.classList.contains("dark") ? "dark" : "light")
const readNothing = () => undefined

const systemDark = () => window.matchMedia("(prefers-color-scheme: dark)")
const isDark = (mode: ThemeMode) => (mode === "system" ? systemDark().matches : mode === "dark")

// Swapping a theme changes every color at once; transitions would make each element ease on its own clock.
function withoutTransitions(change: () => void) {
  const style = document.createElement("style")
  style.textContent = "*,*::before,*::after{transition:none!important}"
  document.head.appendChild(style)
  change()
  getComputedStyle(document.body) // flush styles while transitions are off
  setTimeout(() => style.remove(), 1)
}

type HotkeyFallbacks = { dark: string; light: string }

function ThemeProvider({
  themes,
  storageKey,
  hotkeyFallbacks,
  children,
}: {
  themes: ThemeOption[]
  /** Where the visitor's choice is remembered in localStorage; the same key the head script reads. */
  storageKey: string
  /** Where D lands on a side (dark or light) the visitor has not picked a theme on yet. */
  hotkeyFallbacks: HotkeyFallbacks
  children: React.ReactNode
}) {
  const theme = React.useSyncExternalStore(subscribe, readTheme, readNothing)
  const resolvedMode = React.useSyncExternalStore<"dark" | "light" | undefined>(subscribe, readMode, readNothing)

  const setTheme = React.useCallback(
    (name: string) => {
      const next = themes.find((candidate) => candidate.name === name)
      if (!next) return

      withoutTransitions(() => {
        document.documentElement.dataset.theme = next.name
        document.documentElement.classList.toggle("dark", isDark(next.mode))
      })
      try {
        localStorage.setItem(storageKey, next.name)
      } catch {
        // Without storage the choice lasts until the page closes.
      }
      notify()
    },
    [themes, storageKey]
  )

  const mode = themes.find((candidate) => candidate.name === theme)?.mode

  // A system theme tracks the OS appearance while it is open.
  React.useEffect(() => {
    if (mode !== "system") return
    const query = systemDark()
    const follow = () => {
      document.documentElement.classList.toggle("dark", query.matches)
      notify()
    }
    query.addEventListener("change", follow)
    return () => query.removeEventListener("change", follow)
  }, [mode])

  // Browser chrome (the mobile address bar) should match the page canvas of the active theme.
  React.useEffect(() => {
    const canvas = getComputedStyle(document.documentElement).getPropertyValue("--background").trim()
    if (canvas) document.querySelector('meta[name="theme-color"]')?.setAttribute("content", canvas)
  }, [theme, resolvedMode])

  const value = React.useMemo(
    () => ({ theme, resolvedMode, themes, setTheme }),
    [theme, resolvedMode, themes, setTheme]
  )

  return (
    <ThemeContext value={value}>
      <ThemeHotkey fallbacks={hotkeyFallbacks} />
      {children}
    </ThemeContext>
  )
}

function useTheme() {
  const context = React.useContext(ThemeContext)
  if (!context) throw new Error("useTheme must be used inside <ThemeProvider>")
  return context
}

// D flips between dark and light. Each side remembers the theme last used there, so a visitor
// who picked Nord and pressed D twice lands back on Nord; the first flip from a side they never
// chose goes to the fallbacks the provider was given.

/** Whether a keystroke belongs to what the visitor is typing in, so single-key shortcuts leave it alone. */
function isInteractiveTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) {
    return false
  }

  return (
    target.isContentEditable ||
    target.tagName === "INPUT" ||
    target.tagName === "TEXTAREA" ||
    target.tagName === "SELECT" ||
    // An open theme picker is a listbox or a dialog; keys there are its own, not shortcuts.
    target.closest('[role="listbox"], [role="combobox"], [role="dialog"]') !== null
  )
}

function ThemeHotkey({ fallbacks }: { fallbacks: HotkeyFallbacks }) {
  const { theme, resolvedMode, themes, setTheme } = useTheme()
  const remembered = React.useRef<Partial<Record<"dark" | "light", string>>>({})
  const mode = themes.find((candidate) => candidate.name === theme)?.mode

  // A system theme is both sides at once, so it is never remembered as either.
  React.useEffect(() => {
    if (theme && (mode === "dark" || mode === "light")) remembered.current[mode] = theme
  }, [theme, mode])

  React.useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented || event.repeat) return
      if (event.metaKey || event.ctrlKey || event.altKey) return
      if (event.key.toLowerCase() !== "d") return
      if (isInteractiveTarget(event.target)) return

      const other = resolvedMode === "dark" ? "light" : "dark"
      const target = remembered.current[other] ?? fallbacks[other]
      if (themes.some((candidate) => candidate.name === target)) setTheme(target)
    }

    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [resolvedMode, themes, setTheme, fallbacks])

  return null
}

export { ThemeProvider, useTheme, isInteractiveTarget }

"use client"

import { flushSync } from "react-dom"

const REVEAL_MS = 750 // how long the chosen theme takes to spread over the page

// Confirming spreads the new theme over the page from the chosen card: a circle that grows until it
// covers the far corner. A View Transition snapshots the page in the old theme and shows the new
// one through the circle (theme.css turns its default cross-fade off). Without View Transitions,
// or with reduced motion, the theme just switches.
export function revealTheme(apply: () => void, origin: { x: number; y: number } | undefined, reduced: boolean) {
  if (reduced || !origin || !("startViewTransition" in document)) return apply()
  const root = document.documentElement
  root.classList.add("theme-reveal")
  const transition = document.startViewTransition(() => flushSync(apply))
  const { x, y } = origin
  const radius = Math.hypot(Math.max(x, innerWidth - x), Math.max(y, innerHeight - y))
  transition.ready
    .then(() =>
      root.animate(
        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${radius}px at ${x}px ${y}px)`] },
        { duration: REVEAL_MS, easing: "cubic-bezier(0.65, 0, 0.35, 1)", pseudoElement: "::view-transition-new(root)" },
      ),
    )
    .catch(() => {})
  transition.finished.finally(() => root.classList.remove("theme-reveal"))
}

/*
 * Themes. Each palette theme (head.ts) sets the --om-* slots below on any [data-theme]
 * element, from CSS generated in the root layout: <html> for the page, or a single element
 * that should draw in another theme (the theme picker's preview cards). The mapping is
 * declared on every [data-theme] so tokens resolve against that element's own slots. It sits
 * in :where() at zero specificity, so the palette blocks and any hand-written theme
 * (a CssTheme, which writes the region tokens itself) always win. Components only
 * ever see the region tokens, so a theme never has to know they exist.
 *
 * Two names collide with omarchy and are mapped deliberately: its `accent` is the brand color,
 * so it becomes our primary and focus ring, while shadcn's `--accent` is a quiet hover surface
 * and takes its `selection`. Its `muted` is a de-emphasized ink, so it becomes dividers and
 * input edges. `orange` and `brown` are optional in a palette, so they borrow a neighbour.
 */
:root {
  color-scheme: light;
}

:root.dark {
  color-scheme: dark;
}

:where(:root, [data-theme]) {
  --om-orange: var(--om-yellow);
  --om-brown: var(--om-red);
  --background: var(--om-dark-background);
  --foreground: var(--om-foreground);
  --card: var(--om-background);
  --card-foreground: var(--om-foreground);
  --popover: var(--om-dark-background);
  --popover-foreground: var(--om-foreground);
  --primary: var(--om-accent);
  --primary-foreground: var(--om-on-accent);
  --secondary: var(--om-lighter-background);
  --secondary-foreground: var(--om-bright-foreground);
  --muted: var(--om-lighter-background);
  --muted-foreground: var(--om-muted-foreground);
  --accent: var(--om-selection);
  --accent-foreground: var(--om-bright-foreground);
  --destructive: var(--om-red);
  --destructive-foreground: var(--om-on-red);
  --success: var(--om-green);
  --border: var(--om-muted);
  --input: var(--om-muted);
  --ring: var(--om-accent);
  --chart-1: var(--om-cyan);
  --chart-2: var(--om-green);
  --chart-3: var(--om-yellow);
  --chart-4: var(--om-magenta);
  --chart-5: var(--om-blue);
  --sidebar: var(--om-background);
  --sidebar-foreground: var(--om-foreground);
  --sidebar-primary: var(--om-accent);
  --sidebar-primary-foreground: var(--om-on-accent);
  --sidebar-accent: var(--om-selection);
  --sidebar-accent-foreground: var(--om-bright-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--om-accent);
  --selection: var(--om-selection);
  --selection-foreground: var(--om-bright-foreground);
  /* The project cards take eight tints, one per hue slot (an accent is nearly always one of them already). */
  --tint-1: var(--om-green);
  --tint-2: var(--om-magenta);
  --tint-3: var(--om-blue);
  --tint-4: var(--om-yellow);
  --tint-5: var(--om-red);
  --tint-6: var(--om-brown);
  --tint-7: var(--om-cyan);
  --tint-8: var(--om-orange);
  --radius: 0.625rem;
}

/* A palette's `muted` is an ink, which on a dark canvas is too loud for hairlines. */
:where(.dark) {
  --border: color-mix(in oklab, var(--om-muted) 55%, transparent);
}

/* A new theme spreads through a growing circle that revealTheme (reveal.ts) animates itself,
   so the default cross-fade stays off while it runs. */
html.theme-reveal::view-transition-old(root),
html.theme-reveal::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}

@theme inline {
  --color-success: var(--success);
}
